void dei_ask_init(void)	
{	
    memset(&dei_ask,0,sizeof(dei_ask));
    
    wake_set_sleep_cpu_freq(CPU_FREQ_3MHZ);
    
    irq_user_init() ; 
    
    dei_ask.rx_irq = os_irq_create() ; 
    
    dei_ask.state = dei_ask_state_header;
    
    dei_ask.last_button = DEI_ASK_BUTTON_UNKNOWN;
                        
    irq_user_register( (Irq_User_Func) dei_ask_handler_irq_user);     
    wake_register    ( (Wake_Func)     dei_ask_handler_wake    );
    
    dei_ask_database_init ();
    
    dei_ask_bit_time_set  ();    
    dei_ask_fiq_mode_leave();

    dei_ask_notify_init   ();

    //start the keeloq task
    {
        Tsk tsk  ; 
        
        tsk = os_tsk_create (dei_ask_task , TASK_DEI_ASK_PRI , TASK_DEI_ASK_STK , 0 , TASK_DEI_ASK_NAME ) ;
    
        os_tsk_start (tsk , 0) ;  
    }
}

